{
    public static string Html(string umbracoVersion) => $$"""
        <!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{GeneralConstants.ClientName}} · API Status</title><style>*{box-sizing:border-box}html,body{margin:0;min-height:100%}body{display:flex;justify-content:center;align-items:flex-start;padding:12vh 16px 16px;background:#fdf1ef;color:#fff;font:14px/1.5 -apple-system,'Segoe UI',system-ui,sans-serif;-webkit-font-smoothing:antialiased}.card{position:relative;width:100%;max-width:440px;padding:32px;background:#1b264f;border-radius:20px;overflow:hidden;box-shadow:0 24px 48px -24px rgba(27,38,79,.6)}.bg{position:absolute;right:-70px;top:-70px;width:240px;height:240px;opacity:.12;pointer-events:none}.top{position:relative;display:flex;align-items:center;gap:12px}.top svg{width:38px;height:38px;flex-shrink:0}.top strong{font-size:15px;letter-spacing:.08em}.tag{margin-left:auto;display:inline-flex;align-items:center;gap:7px;padding:5px 12px;border-radius:999px;background:rgba(27,178,107,.15);color:#5fe0a3;font-size:12px;font-weight:600}.dot{width:7px;height:7px;border-radius:50%;background:#1bb26b;animation:b 1.6s ease-in-out infinite}@keyframes b{50%{opacity:.3} }@media (prefers-reduced-motion:reduce){.dot{animation:none} }h1{position:relative;margin:40px 0 6px;font-size:30px;line-height:1.2;font-weight:700;letter-spacing:-.01em}.sub{position:relative;margin:0;color:#f5c1bc;font-size:15px}.grid{position:relative;display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:32px}.tile{padding:14px 16px;border-radius:12px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.08)}.tile span{display:block;color:#a9b0d1;font-size:12px;font-weight:600;letter-spacing:.06em;text-transform:uppercase}.tile b{display:block;margin-top:4px;font-size:17px;font-weight:700}</style></head><body><main class="card"><svg class="bg" viewBox="0 0 32 32" aria-hidden="true"><circle cx="16" cy="16" r="15" fill="none" stroke="#f5c1bc" stroke-width="1"/><path d="M10 10v7a6 6 0 0 0 12 0v-7" fill="none" stroke="#f5c1bc" stroke-width="2" stroke-linecap="round"/></svg><div class="top"><svg viewBox="0 0 32 32" aria-hidden="true"><circle cx="16" cy="16" r="16" fill="#f5c1bc"/><path d="M10 10v7a6 6 0 0 0 12 0v-7" fill="none" stroke="#1b264f" stroke-width="2.6" stroke-linecap="round"/></svg><strong>{{GeneralConstants.ClientName}}</strong><span class="tag"><span class="dot"></span>Live</span></div><h1>API is Running</h1><p class="sub">All systems operational</p><div class="grid"><div class="tile"><span>API Status</span><b>Operational</b></div><div class="tile"><span>Umbraco</span><b>v{{umbracoVersion}}</b></div></div></main></body></html>
